/// <summary>
/// MPJ_15907_LiquorAndTobaccoLicence
/// Service class to run Update sales orders with latest tobacco Licence logic
/// </summary>
class METSOTobaccoLicUpdateService extends SysOperationServiceBase
{    
    const real  RetryNum = 3;
}

Method.Source:
    /// <summary>
    /// MPJ_15907_LiquorAndTobaccoLicence
    /// Method to Update sales orders with latest tobacco Licence.
    /// </summary>
    /// <param name = "_contract"> METRebateInclusionsUpdateContract </param>
    public void processOperation(METSOTobaccoLicUpdateContract _contract)
    {
        QueryRun                    queryRun;
        METCustTobaccoLicenseTable  custTobaccoLicenseTable;
        SalesTable                  salesTable;
        SalesLine                   salesLine;

        queryRun = new QueryRun(_contract.getQuery());
        while(queryRun.next())
        {
            custTobaccoLicenseTable = queryRun.get(tablenum(METCustTobaccoLicenseTable));
            salesTable = queryRun.get(tablenum(SalesTable));
            try
            {
                if(custTobaccoLicenseTable.TobaccoLicenceExpiry >= salesTable.ShippingDateRequested)
                {                
                    ttsbegin;
                    salesTable.selectForUpdate(true);
                    salesTable.METCustTobaccoReasonCode = '';
                    if(salesTable.validateWrite())
                    {
                        salesTable.update();
                    }

                    update_recordset salesLine
                        setting METCustTobaccoReasonCode = '',
                                Blocked = Noyes::No
                            where salesLine.SalesId == salesTable.SalesId
                               && salesLine.SalesStatus == SalesStatus::Backorder
                               && salesLine.Blocked == NoYes::Yes;
                    ttscommit;
                }
                else
                {
                    CustTable           custTable;

                    custTable = queryRun.get(tablenum(CustTable));
                    ttsbegin;
                    salesTable.selectForUpdate(true);
                    salesTable.METCustTobaccoReasonCode = LogisticsAddressState::find(custTable.PartyCountry, custTable.PartyState).METTobaccoReasonCode;
                    if(salesTable.validateWrite())
                    {
                        salesTable.update();
                    }

                    WHSInventTable      whsInventTable;
                    METCustParameters   METCustParameters = METCustParameters::Find();

                    update_recordset salesLine
                        setting METCustTobaccoReasonCode = salesTable.METCustTobaccoReasonCode,
                        Blocked = NoYes::Yes
                            where salesLine.SalesId == salesTable.SalesId
                               && salesLine.SalesStatus == SalesStatus::Backorder
                               && salesLine.Blocked == NoYes::No
                               exists join firstonly whsInventTable
                                    where whsInventTable.ItemId == salesLine.ItemId
                                       && whsInventTable.FilterCode[1] == METCustParameters.TobaccoFilterCodes;
                    ttscommit;
                }
            }
            catch(Exception::UpdateConflict)
            {
                Info("@MET:METSOUpdateConflict");
                throw Exception::UpdateConflictNotRecovered;
            }
            catch(Exception::Deadlock)
            {
                if (xSession::currentRetryCount() >= RetryNum)
                {
                    throw Exception::UpdateConflictNotRecovered;
                }
                retry;
            }
            catch(Exception::CLRError)
            {
                System.Exception netExcepn;
                info("@MET:METRebateCLRException");
                netExcepn = CLRInterop::getLastException();
                info(netExcepn.ToString());
            }
            catch(Exception::Error)
            {
                Info("@MET:METSOUpdateError");
            }

        }

    }
